\draw (0,3)--(0.8,3.6)--(2.1,3.6);
\path (2.1,-0.3) node[below] {(a)};
\begin{scope}[shift={(6,0)}]
\draw (0,0)--(4.2,0)--(4.2,1.1)--(2.8,1.1)--(2.8,2.7)--(1.4,2.7)--(1.4,1.1)--(0,1.1)--cycle;
